changeSet.sql:
alter table zugriff_protokoll drop constraint zugriff_protokoll_aktion_ck;
alter table zugriff_protokoll add constraint zugriff_protokoll_aktion_ck
    check (aktion in ('ERFASSEN', 'ANZEIGEN', 'HERUNTERLADEN', 'AENDERN', 'BESTAETIGEN', 'VERWERFEN',
        'WIEDERHOLEN', 'EXPORTIEREN', 'VERWEIGERT', 'SPERRE_KONFLIKT', 'REGEL_AENDERN',
        'KONFIGURATION_AENDERN', 'WISSEN_ANZEIGEN', 'WISSEN_ANNEHMEN', 'WISSEN_VERWERFEN',
        'WISSEN_INGEST', 'WISSEN_LINT', 'KONTAKT_ZUSAMMENFUEHREN', 'KONTAKT_INAKTIV', 'KONTAKT_AKTIV'));
